def check_constraint(m):
    """Checks if m(m+1) is divisible by 6."""
    if m <= 0:
        return False
    return (m * (m + 1)) % 6 == 0

print("Testing small values of m:")
for m in range(1, 15):
    result = "PASS" if check_constraint(m) else "FAIL"
    print(f"m={m}: {result} (K={m*(m+1)//6 if check_constraint(m) else 'Not Int'})")

def solve():
    results = []
    for m in range(1, 101):
        total_sum = m * (m + 1) // 2
        if total_sum % 3 != 0:
            results.append((m, False, "Sum not divisible by 3"))
            continue

        S = total_sum // 3
        dp = [0] * (S + 1)
        dp[0] = 1

        for i in range(1, m + 1):
            new_dp = [0] * (S + 1)
            for s1 in range(S + 1):
                # Options for i:
                # 1. i is not in X or Y:
                new_dp[s1] |= dp[s1]
                # 2. i is in Y:
                new_dp[s1] |= (dp[s1] << i)
                # 3. i is in X:
                if s1 >= i:
                    new_dp[s1] |= dp[s1-i]

            # Masking
            mask = (1 << (S + 1)) - 1
            for s1 in range(S + 1):
                dp[s1] = new_dp[s1] & mask

        if (dp[S] >> S) & 1:
            results.append((m, True, "Found"))
        else:
            results.append((m, False, "Not found"))
    return results

